def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    tog = {0: 8, 8: 0, 6: 7, 7: 6}
    lines = []
    for x in range(W):
        if g[0, x] == 4 and g[H-1, x] == 4:
            lines.append([(y, x) for y in range(1, H-1)])
    for y in range(H):
        if g[y, 0] == 4 and g[y, W-1] == 4:
            lines.append([(y, x) for x in range(1, W-1)])
    for cells in lines:
        for (y, x) in cells:
            v = int(g[y, x])
            if v in tog:
                g[y, x] = tog[v]
        emit(g, "Toggle 0<->8 and 6<->7 on the line between a pair of facing 4 markers")
    emit(g, "Final grid")
    return g
